=== FILE: deep_counter_props.sv ===
// Formal property wrapper for deep_counter (see interface_spec.md).
// Interface-level properties only; no assumptions on the inputs.
// Immediate assertions inside always blocks (open Yosys front-end subset).
module deep_counter_formal #(
    parameter integer LIMIT = 99
) (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire clr
);
    wire [6:0] count;
    wire       carry;

    deep_counter #(.LIMIT(LIMIT)) dut (
        .clk  (clk),
        .rst_n(rst_n),
        .en   (en),
        .clr  (clr),
        .count(count),
        .carry(carry)
    );

    // First-cycle guard for $past, and a flag that a reset edge has occurred.
    reg f_past_valid = 1'b0;
    reg f_reset_seen = 1'b0;
    always @(posedge clk) begin
        f_past_valid <= 1'b1;
        if (!rst_n)
            f_reset_seen <= 1'b1;
    end

    // Transition rules, checked at each clock edge.
    always @(posedge clk) begin
        // [req:DC-RESET] reset low at an edge clears count
        if (f_past_valid && !$past(rst_n))
            assert(count == 7'd0);

        // [req:DC-CLEAR] clr clears count whatever en is
        if (f_past_valid && $past(rst_n) && $past(clr))
            assert(count == 7'd0);

        // [req:DC-COUNT] enabled count below LIMIT goes up by one
        if (f_past_valid && $past(rst_n) && !$past(clr) && $past(en)
            && ($past(count) < LIMIT))
            assert(count == $past(count) + 7'd1);

        // [req:DC-COUNT] enabled count at LIMIT wraps to 0
        if (f_past_valid && $past(rst_n) && !$past(clr) && $past(en)
            && ($past(count) == LIMIT))
            assert(count == 7'd0);

        // [req:DC-HOLD] no clr, no en: count does not change
        if (f_past_valid && $past(rst_n) && !$past(clr) && !$past(en))
            assert(count == $past(count));
    end

    // Invariants, checked at every step.
    always @(*) begin
        // [req:DC-RANGE] after reset, count never exceeds LIMIT
        // (also the helper invariant that makes induction close)
        if (f_reset_seen)
            assert(count <= LIMIT);

        // [req:DC-CARRY] carry is combinational: en && !clr && count == LIMIT
        assert(carry == (en && !clr && (count == LIMIT)));
    end

    // Covers: scenarios the proof must still allow (vacuity check).
    always @(posedge clk) begin
        if (f_reset_seen) begin
            // full state reached after counting up from reset
            cover(count == LIMIT);
            // carry asserted after reset
            cover(carry);
            // simultaneous clr and en at LIMIT (carry must be suppressed)
            cover(en && clr && (count == LIMIT));
        end
        if (f_past_valid && f_reset_seen) begin
            // a wrap from LIMIT to 0 after reset
            cover($past(f_reset_seen) && $past(rst_n) && $past(carry)
                  && (count == 7'd0));
            // clear with en high from a non-zero count
            cover($past(rst_n) && $past(clr) && $past(en)
                  && ($past(count) != 7'd0));
            // hold at a non-zero count
            cover($past(rst_n) && !$past(clr) && !$past(en)
                  && (count != 7'd0));
        end
    end
endmodule
=== END FILE ===
